const D = { hue: 128, energy: .6, speed: 1, density: .5, scale: 1, x: .5, y: .82, head: 1, limb: 1, glow: .6, seed: 0, pose: 'auto', style: 'xray', act: 'greet' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
