  bob = -Math.abs(Math.sin(bt * Math.PI)) * 6 * eAmp - kick * 4;
  tilt = Math.sin(K.t * .6) * .05 + hip * .002;
  headB = Math.sin(bt * Math.PI + .6) * 4 * eAmp;
  headT = -tilt * 1.4 + Math.sin(K.t * .8) * .06;
